#include "trace_gpu.h"

#include "photoreal_shaders.h"  // generated by build.py: kTraceCs, kGatherCs (DXBC)

#include <algorithm>
#include <cstdio>
#include <cstring>

namespace photoreal
{
    namespace
    {
        // An 8x8 group's tile is SV_GroupID.y; its 64 groups are SV_GroupID.x.
        constexpr UINT kGroupsPerTile = (kTileSize / 8) * (kTileSize / 8);
        // The counters buffer's uints: the trace kernel's, then the gather kernel's, padded.
        constexpr UINT kCounterSlots = 32;
        static_assert(kAllCounters <= kCounterSlots);

        HRESULT raw_buffer(ID3D11Device *device, UINT bytes, const void *data, ComPtr<ID3D11Buffer> &buffer, ComPtr<ID3D11ShaderResourceView> &srv)
        {
            D3D11_BUFFER_DESC desc = {};
            desc.ByteWidth = bytes;
            desc.Usage = D3D11_USAGE_DEFAULT;
            desc.BindFlags = D3D11_BIND_SHADER_RESOURCE;
            desc.MiscFlags = D3D11_RESOURCE_MISC_BUFFER_ALLOW_RAW_VIEWS;
            const D3D11_SUBRESOURCE_DATA initial = { data, 0, 0 };
            HRESULT hr = device->CreateBuffer(&desc, data ? &initial : nullptr, buffer.ReleaseAndGetAddressOf());
            if (FAILED(hr))
                return hr;
            D3D11_SHADER_RESOURCE_VIEW_DESC view = {};
            view.Format = DXGI_FORMAT_R32_TYPELESS;
            view.ViewDimension = D3D11_SRV_DIMENSION_BUFFEREX;
            view.BufferEx.NumElements = bytes / 4;
            view.BufferEx.Flags = D3D11_BUFFEREX_SRV_FLAG_RAW;
            return device->CreateShaderResourceView(buffer.Get(), &view, srv.ReleaseAndGetAddressOf());
        }

        HRESULT structured_buffer(ID3D11Device *device, UINT stride, UINT count, ComPtr<ID3D11Buffer> &buffer, ComPtr<ID3D11UnorderedAccessView> &uav,
            ComPtr<ID3D11ShaderResourceView> *srv)
        {
            D3D11_BUFFER_DESC desc = {};
            desc.ByteWidth = stride * count;
            desc.Usage = D3D11_USAGE_DEFAULT;
            desc.BindFlags = D3D11_BIND_UNORDERED_ACCESS | (srv ? D3D11_BIND_SHADER_RESOURCE : 0);
            desc.MiscFlags = D3D11_RESOURCE_MISC_BUFFER_STRUCTURED;
            desc.StructureByteStride = stride;
            HRESULT hr = device->CreateBuffer(&desc, nullptr, buffer.ReleaseAndGetAddressOf());
            if (FAILED(hr))
                return hr;
            D3D11_UNORDERED_ACCESS_VIEW_DESC u = {};
            u.Format = DXGI_FORMAT_UNKNOWN;
            u.ViewDimension = D3D11_UAV_DIMENSION_BUFFER;
            u.Buffer.NumElements = count;
            hr = device->CreateUnorderedAccessView(buffer.Get(), &u, uav.ReleaseAndGetAddressOf());
            if (FAILED(hr) || !srv)
                return hr;
            D3D11_SHADER_RESOURCE_VIEW_DESC s = {};
            s.Format = DXGI_FORMAT_UNKNOWN;
            s.ViewDimension = D3D11_SRV_DIMENSION_BUFFER;
            s.Buffer.NumElements = count;
            return device->CreateShaderResourceView(buffer.Get(), &s, srv->ReleaseAndGetAddressOf());
        }

        // A CPU-readable twin of a structured buffer of count elements of stride bytes, which CopyResource can fill.
        HRESULT staging_buffer(ID3D11Device *device, UINT stride, UINT count, ComPtr<ID3D11Buffer> &buffer)
        {
            D3D11_BUFFER_DESC desc = {};
            desc.ByteWidth = stride * count;
            desc.Usage = D3D11_USAGE_STAGING;
            desc.CPUAccessFlags = D3D11_CPU_ACCESS_READ;
            desc.MiscFlags = D3D11_RESOURCE_MISC_BUFFER_STRUCTURED;
            desc.StructureByteStride = stride;
            return device->CreateBuffer(&desc, nullptr, buffer.ReleaseAndGetAddressOf());
        }

        std::string megabytes(uint64_t bytes)
        {
            char text[32];
            std::snprintf(text, sizeof text, "%.1f MB", bytes / 1e6);
            return text;
        }

        bool power_of_two(uint32_t v) { return v != 0 && (v & (v - 1)) == 0; }
    }

    void TraceGpu::init(ID3D11Device *device, ID3D11DeviceContext1 *context)
    {
        *this = TraceGpu {};
        device_ = device;
        context_ = context;
    }

    void TraceGpu::free_scene()
    {
        node_buffer_.Reset();
        triangle_buffer_.Reset();
        alpha_buffer_.Reset();
        node_srv_.Reset();
        triangle_srv_.Reset();
        alpha_srv_.Reset();
        uploading_.reset();
        uploading_alpha_.reset();
        light_.reset();
        sky_buffer_.Reset();
        sky_srv_.Reset();
        gathering_ = false;
        target_ = 0;
        alpha_bytes_ = 0;
        uploaded_ = 0;
        upload_presents_ = 0;
        triangles_ = node_count_ = 0;
        hash_ = 0;
        key_.reset();
        started_constants_.reset();
        uploaded_constants_.reset();
        schedule_ = {};
        save_.reset();
    }

    void TraceGpu::building()
    {
        free_scene();
        state_ = TraceState::building;
        why_.clear();
    }

    void TraceGpu::fail(const std::string &why)
    {
        free_scene();
        state_ = TraceState::failed;
        why_ = why;
    }

    void TraceGpu::release()
    {
        free_scene();
        history_.Reset();
        history_uav_.Reset();
        history_srv_.Reset();
        gather_hit_.Reset();
        gather_sky_.Reset();
        gather_hit_uav_.Reset();
        gather_sky_uav_.Reset();
        gather_hit_srv_.Reset();
        gather_sky_srv_.Reset();
        tiles_.Reset();
        tiles_srv_.Reset();
        size_ = {};
        tile_count_ = 0;
        state_ = TraceState::none;
        why_.clear();
    }

    void TraceGpu::stale(const std::string &why)
    {
        if (state_ != TraceState::ready)
            return;
        state_ = TraceState::stale;
        why_ = why;
    }

    bool TraceGpu::make_shader()
    {
        if (cs_ && gather_cs_ && constants_ && gather_constants_)
            return true;
        HRESULT hr = device_->CreateComputeShader(kTraceCs, sizeof kTraceCs, nullptr, cs_.ReleaseAndGetAddressOf());
        if (SUCCEEDED(hr))
            hr = device_->CreateComputeShader(kGatherCs, sizeof kGatherCs, nullptr, gather_cs_.ReleaseAndGetAddressOf());
        if (FAILED(hr))
        {
            fail("the trace kernels could not be made (" + hresult_text("CreateComputeShader", hr) + ")");
            return false;
        }
        D3D11_BUFFER_DESC desc = {};
        desc.ByteWidth = sizeof(TraceConstants);
        desc.Usage = D3D11_USAGE_DYNAMIC;
        desc.BindFlags = D3D11_BIND_CONSTANT_BUFFER;
        desc.CPUAccessFlags = D3D11_CPU_ACCESS_WRITE;
        hr = device_->CreateBuffer(&desc, nullptr, constants_.ReleaseAndGetAddressOf());
        desc.ByteWidth = sizeof(GatherConstants);
        if (SUCCEEDED(hr))
            hr = device_->CreateBuffer(&desc, nullptr, gather_constants_.ReleaseAndGetAddressOf());
        if (FAILED(hr))
        {
            fail("the trace's constant buffers could not be made (" + hresult_text("CreateBuffer", hr) + ")");
            return false;
        }
        return true;
    }

    bool TraceGpu::begin_upload(std::shared_ptr<const Bvh> bvh, std::shared_ptr<const std::vector<uint32_t>> alpha, std::shared_ptr<const SceneLight> light,
        uint64_t generation, bool &buffer)
    {
        buffer = false;
        free_scene();
        if (!make_shader())
            return false;
        const uint64_t node_bytes = bvh->nodes.size() * sizeof(BvhNode), triangle_bytes = bvh->triangles.size() * sizeof(BvhTriangle);
        const uint64_t alpha_bytes = alpha ? alpha->size() * 4 : 0;
        if (node_bytes > (256ull << 20) || triangle_bytes > (256ull << 20) || alpha_bytes > (256ull << 20))
        {
            buffer = true;
            fail("its buffers would pass 256 MB: " + megabytes(node_bytes) + " of nodes, " + megabytes(triangle_bytes) + " of triangles and "
                + megabytes(alpha_bytes) + " of alpha tests");
            return false;
        }
        // A scene without alpha tests binds 16 bytes of zeros, which no triangle's record reads.
        const uint32_t empty[4] = {};
        HRESULT hr = raw_buffer(device_.Get(), static_cast<UINT>(node_bytes), nullptr, node_buffer_, node_srv_);
        if (SUCCEEDED(hr))
            hr = raw_buffer(device_.Get(), static_cast<UINT>(triangle_bytes), nullptr, triangle_buffer_, triangle_srv_);
        if (SUCCEEDED(hr))
            hr = raw_buffer(device_.Get(), alpha_bytes != 0 ? static_cast<UINT>(alpha_bytes) : 16, alpha_bytes != 0 ? nullptr : empty, alpha_buffer_, alpha_srv_);
        // The sky map is small and goes up whole.
        if (SUCCEEDED(hr) && light && light->sky.texels.size() == size_t(kSkyMapSide) * kSkyMapSide * 4)
            hr = raw_buffer(device_.Get(), static_cast<UINT>(light->sky.texels.size() * 4), light->sky.texels.data(), sky_buffer_, sky_srv_);
        if (FAILED(hr))
        {
            buffer = true;
            fail("its buffers of " + megabytes(node_bytes) + " of nodes, " + megabytes(triangle_bytes) + " of triangles and " + megabytes(alpha_bytes)
                + " of alpha tests could not be made (" + hresult_text("CreateBuffer", hr) + ")");
            return false;
        }
        light_ = sky_srv_ ? std::move(light) : nullptr;
        uploading_alpha_ = alpha_bytes != 0 ? std::move(alpha) : nullptr;
        alpha_bytes_ = alpha_bytes;
        uploading_ = std::move(bvh);
        generation_ = generation;
        triangles_ = static_cast<uint32_t>(uploading_->triangles.size());
        node_count_ = static_cast<uint32_t>(uploading_->nodes.size());
        hash_ = uploading_->hash;
        state_ = TraceState::uploading;
        why_.clear();
        return true;
    }

    bool TraceGpu::upload_step()
    {
        if (state_ != TraceState::uploading || !uploading_)
            return false;
        upload_presents_++;
        // The nodes, then the triangles, then the alpha buffer, as one run of bytes.
        const struct Part
        {
            ID3D11Buffer *buffer;
            const uint8_t *data;
            uint64_t bytes;
        } parts[] = {
            { node_buffer_.Get(), reinterpret_cast<const uint8_t *>(uploading_->nodes.data()), uploading_->nodes.size() * sizeof(BvhNode) },
            { triangle_buffer_.Get(), reinterpret_cast<const uint8_t *>(uploading_->triangles.data()), uploading_->triangles.size() * sizeof(BvhTriangle) },
            { alpha_buffer_.Get(), uploading_alpha_ ? reinterpret_cast<const uint8_t *>(uploading_alpha_->data()) : nullptr, alpha_bytes_ },
        };
        uint64_t total = 0;
        for (const Part &part : parts)
            total += part.bytes;
        const uint64_t end = std::min(total, uploaded_ + kTraceUploadBytes);
        // UpdateSubresource returns nothing; the buffers were made, and a box inside them cannot fail.
        while (uploaded_ < end)
        {
            uint64_t base = 0;
            const Part *part = parts;
            while (uploaded_ >= base + part->bytes)
                base += part++->bytes;
            const uint64_t stop = std::min(end, base + part->bytes);
            const D3D11_BOX box = { static_cast<UINT>(uploaded_ - base), 0, 0, static_cast<UINT>(stop - base), 1, 1 };
            context_->UpdateSubresource(part->buffer, 0, &box, part->data + (uploaded_ - base), 0, 0);
            uploaded_ = stop;
        }
        if (uploaded_ < total)
            return false;
        uploading_.reset();
        uploading_alpha_.reset();
        state_ = TraceState::ready;
        key_.reset();
        started_constants_.reset();
        schedule_ = {};
        return true;
    }

    TraceFrame TraceGpu::preview(const TraceKey &key, const TraceSettings &settings, const TraceConstants &constants, const GatherSettings &gather_settings,
        const GatherConstants *gather) const
    {
        TraceFrame f;
        f.key = key;
        f.constants = constants;
        f.schedule = schedule_;
        f.gathering = gather != nullptr && sky_srv_ != nullptr;
        if (f.gathering)
        {
            f.gather = *gather;
            f.constants.trace_counts[0] = 0;
        }
        f.target = trace_target(settings, gather_settings, f.gathering);
        const uint32_t tiles = static_cast<uint32_t>(((key.render.width + kTileSize - 1) / kTileSize) * ((key.render.height + kTileSize - 1) / kTileSize));
        f.restart = !key_ ? TraceRestart::scene : trace_restart(*key_, key);
        if (f.restart == TraceRestart::none && schedule_.tiles != tiles)
            f.restart = TraceRestart::render;
        f.reset = f.restart != TraceRestart::none;
        if (f.reset)
        {
            f.schedule.tiles = tiles;
            f.schedule.visits = 0;
            return f;
        }
        // The samples go on with the camera, sun and light they started with.
        if (started_constants_)
        {
            f.constants = held_constants(*started_constants_, f.constants);
            if (f.gathering)
                f.gather = held_gather(started_gather_, f.gather);
        }
        const uint32_t before = trace_passes(f.schedule);
        f.dispatch = trace_next(f.schedule, f.target);
        f.traced = trace_passes(f.schedule) >= 1;
        f.trace_kernel = !f.gathering || trace_kernel_runs(before, settings.sun_samples);
        return f;
    }

    bool TraceGpu::sync(Size render, bool gathering)
    {
        if (!history_ || render != size_)
        {
            gather_hit_.Reset();
            gather_sky_.Reset();
            const std::vector<uint32_t> order = tile_order(render);
            HRESULT hr = structured_buffer(device_.Get(), 16, render.width * render.height, history_, history_uav_, &history_srv_);
            if (SUCCEEDED(hr))
                hr = raw_buffer(device_.Get(), static_cast<UINT>(order.size() * 4), order.data(), tiles_, tiles_srv_);
            if (SUCCEEDED(hr) && !counters_)
                hr = structured_buffer(device_.Get(), 4, kCounterSlots, counters_, counters_uav_, nullptr);
            if (FAILED(hr))
            {
                history_.Reset();
                fail("the trace's history of " + std::to_string(render.width) + "x" + std::to_string(render.height) + " could not be made ("
                    + hresult_text("CreateBuffer", hr) + ")");
                return false;
            }
            size_ = render;
            tile_count_ = static_cast<uint32_t>(order.size());
        }
        // The gather's buffers, the first time a frame gathers at this size: a frame that starts to gather starts its
        // samples again, which clears them.
        if (gathering && !gather_hit_)
        {
            HRESULT hr = structured_buffer(device_.Get(), 16, render.width * render.height, gather_hit_, gather_hit_uav_, &gather_hit_srv_);
            if (SUCCEEDED(hr))
                hr = structured_buffer(device_.Get(), 16, render.width * render.height, gather_sky_, gather_sky_uav_, &gather_sky_srv_);
            if (FAILED(hr))
            {
                gather_hit_.Reset();
                gather_sky_.Reset();
                fail("the gather's buffers of " + std::to_string(render.width) + "x" + std::to_string(render.height) + " could not be made ("
                    + hresult_text("CreateBuffer", hr) + ")");
                return false;
            }
        }
        return true;
    }

    bool TraceGpu::dispatch(const TraceFrame &frame, Size render, ID3D11ShaderResourceView *normals, ID3D11ShaderResourceView *depth,
        ID3D11ShaderResourceView *stencil)
    {
        if (state_ != TraceState::ready || !sync(render, frame.gathering))
            return false;
        ID3D11DeviceContext1 *c = context_.Get();
        if (frame.reset)
        {
            const UINT zero[4] = {};
            c->ClearUnorderedAccessViewUint(history_uav_.Get(), zero);
            if (gather_hit_)
            {
                c->ClearUnorderedAccessViewUint(gather_hit_uav_.Get(), zero);
                c->ClearUnorderedAccessViewUint(gather_sky_uav_.Get(), zero);
            }
            epoch_++;
            restart_ = frame.restart;
            totals_ = {};
            window_ = {};
            window_pass_ = logged_pass_ = 0;
            measures_logged_ = 0;
            mrays_ = 0;
            noise_deviation_ = noise_mean_ = 0;
            noise_pass_ = 0;
            error_ = 0;
            pace_ = {};
            settled_logged_ = false;
            settled_ms_ = 0;
            settled_frames_ = 0;
            // What these samples started with: every later frame's key is held against it, and its constants are theirs.
            key_ = frame.key;
            started_constants_ = frame.constants;
            started_gather_ = frame.gather;
        }
        schedule_ = frame.schedule;
        gathering_ = frame.gathering;
        target_ = frame.target;

        // The constants with a dispatch's first tile, at b0 for the kernel and b1 for the apply draw.
        const auto upload = [&](uint32_t first) {
            TraceConstants constants = frame.constants;
            constants.trace_tiles[0] = first;
            constants.trace_tiles[1] = tile_count_;
            D3D11_MAPPED_SUBRESOURCE mapped;
            const HRESULT result = c->Map(constants_.Get(), 0, D3D11_MAP_WRITE_DISCARD, 0, &mapped);
            if (FAILED(result))
            {
                fail("the trace's constants could not be written (" + hresult_text("Map", result) + ")");
                return false;
            }
            std::memcpy(mapped.pData, &constants, sizeof constants);
            c->Unmap(constants_.Get(), 0);
            uploaded_constants_ = constants;
            return true;
        };
        if (!frame.dispatch)
            return upload(0);
        HRESULT hr = S_OK;

        // The oldest set of queries, unread for four frames, is given up.
        Flight &flight = flights_[next_flight_];
        next_flight_ = (next_flight_ + 1) % flights_.size();
        if (!flight.disjoint)
        {
            const D3D11_QUERY_DESC disjoint = { D3D11_QUERY_TIMESTAMP_DISJOINT, 0 }, stamp = { D3D11_QUERY_TIMESTAMP, 0 };
            hr = device_->CreateQuery(&disjoint, flight.disjoint.ReleaseAndGetAddressOf());
            if (SUCCEEDED(hr))
                hr = device_->CreateQuery(&stamp, flight.begin.ReleaseAndGetAddressOf());
            if (SUCCEEDED(hr))
                hr = device_->CreateQuery(&stamp, flight.middle.ReleaseAndGetAddressOf());
            if (SUCCEEDED(hr))
                hr = device_->CreateQuery(&stamp, flight.end.ReleaseAndGetAddressOf());
            if (SUCCEEDED(hr))
                hr = staging_buffer(device_.Get(), 4, kCounterSlots, flight.counters);
            if (FAILED(hr))
            {
                flight.disjoint.Reset();
                fail("the trace's timestamp queries could not be made (" + hresult_text("CreateQuery", hr) + ")");
                return false;
            }
        }
        const UINT zero[4] = {};
        c->ClearUnorderedAccessViewUint(counters_uav_.Get(), zero);
        if (frame.gathering)
        {
            D3D11_MAPPED_SUBRESOURCE mapped;
            hr = c->Map(gather_constants_.Get(), 0, D3D11_MAP_WRITE_DISCARD, 0, &mapped);
            if (FAILED(hr))
            {
                fail("the gather's constants could not be written (" + hresult_text("Map", hr) + ")");
                return false;
            }
            std::memcpy(mapped.pData, &frame.gather, sizeof frame.gather);
            c->Unmap(gather_constants_.Get(), 0);
            uploaded_gather_ = frame.gather;
        }
        // Both kernels' bindings at once: the trace kernel declares only b0, t0 to t6, u0 and u1; the gather kernel all.
        ID3D11Buffer *const buffers[] = { constants_.Get(), frame.gathering ? gather_constants_.Get() : nullptr };
        ID3D11ShaderResourceView *const srvs[] = { node_srv_.Get(), triangle_srv_.Get(), normals, depth, stencil, tiles_srv_.Get(), alpha_srv_.Get(),
            frame.gathering ? sky_srv_.Get() : nullptr };
        ID3D11UnorderedAccessView *const uavs[] = { history_uav_.Get(), counters_uav_.Get(), frame.gathering ? gather_hit_uav_.Get() : nullptr,
            frame.gathering ? gather_sky_uav_.Get() : nullptr };
        c->CSSetConstantBuffers(0, static_cast<UINT>(std::size(buffers)), buffers);
        c->CSSetShaderResources(0, static_cast<UINT>(std::size(srvs)), srvs);
        c->CSSetUnorderedAccessViews(0, static_cast<UINT>(std::size(uavs)), uavs, nullptr);
        // The game's work so far goes to the GPU first, then each part on its own, so no one submission holds more than
        // schedule_.chunk tiles of the trace, nor the game's work. The timestamps bracket only the first part, inside its
        // own submission: around a flush they would also count the GPU waiting for the rest of the game's frame, which made
        // every frame look over budget and held build 205 at 1 tile a frame. While it gathers, each part is the trace
        // kernel's dispatch, while it runs, then the gather kernel's over the same tiles, and the timestamps bracket both.
        c->Flush();
        c->Begin(flight.disjoint.Get());
        bool uploaded = true;
        const std::vector<TraceDispatch> parts = trace_chunks(*frame.dispatch, tile_count_, schedule_.chunk);
        for (size_t i = 0; i < parts.size(); i++)
        {
            uploaded = upload(parts[i].first);
            if (!uploaded)
                break;
            if (i == 0)
                c->End(flight.begin.Get());
            if (frame.trace_kernel)
            {
                c->CSSetShader(cs_.Get(), nullptr, 0);
                c->Dispatch(kGroupsPerTile, parts[i].count, 1);
            }
            if (i == 0)
                c->End(flight.middle.Get());
            if (frame.gathering)
            {
                c->CSSetShader(gather_cs_.Get(), nullptr, 0);
                c->Dispatch(kGroupsPerTile, parts[i].count, 1);
            }
            if (i == 0)
                c->End(flight.end.Get());
            c->Flush();
        }
        c->End(flight.disjoint.Get());
        // Unbound before the apply draw reads the history as a shader resource.
        ID3D11ShaderResourceView *const no_srvs[std::size(srvs)] = {};
        ID3D11UnorderedAccessView *const no_uavs[std::size(uavs)] = {};
        c->CSSetShaderResources(0, static_cast<UINT>(std::size(no_srvs)), no_srvs);
        c->CSSetUnorderedAccessViews(0, static_cast<UINT>(std::size(no_uavs)), no_uavs, nullptr);
        if (!uploaded)
            return false;
        c->CopyResource(flight.counters.Get(), counters_.Get());
        dispatched_ = true;
        pace_.tiles += frame.dispatch->count;
        flight.pending = true;
        flight.tiles = frame.dispatch->count;
        flight.measured = parts.empty() ? 0 : parts[0].count;
        flight.passes_before = trace_passes(TraceSchedule { schedule_.tiles, schedule_.visits - frame.dispatch->count, schedule_.batch });
        flight.passes_after = trace_passes(schedule_);
        flight.epoch = epoch_;
        return true;
    }

    std::string TraceGpu::pace_text(uint32_t from_pass, uint32_t to_pass) const
    {
        const Pace &p = pace_;
        const uint32_t frames = p.traced + p.idle;
        const double per_tile = p.measured_tiles != 0 ? 1.0 / double(p.measured_tiles) : 0;
        char line[400];
        std::snprintf(line, sizeof line, " Passes %u to %u took %.1f s over %u frames, %u of them tracing %.1f tiles and %.1f ms each and the others %.1f ms "
            "each; the kernels' GPU time was %.3f ms a tile for the trace and %.3f for the gather, %.1f s of it.", from_pass + 1, to_pass,
            (p.traced_ms + p.idle_ms) / 1000.0, frames, p.traced, p.traced != 0 ? double(p.tiles) / p.traced : 0.0, p.traced != 0 ? p.traced_ms / p.traced : 0.0,
            p.idle != 0 ? p.idle_ms / p.idle : 0.0, p.trace_ms * per_tile, p.gather_ms * per_tile, (p.trace_ms + p.gather_ms) * per_tile * double(p.tiles) / 1000.0);
        return line;
    }

    TraceGpu::Poll TraceGpu::poll(const TraceSettings &settings)
    {
        Poll out;
        // This present's frame: its wall time goes to the frames that traced or to the others.
        const auto now = std::chrono::steady_clock::now();
        if (polled_)
        {
            const double frame_ms = std::chrono::duration<double, std::milli>(now - polled_at_).count();
            (dispatched_ ? pace_.traced_ms : pace_.idle_ms) += frame_ms;
            (dispatched_ ? pace_.traced : pace_.idle)++;
            // Once every pixel has its samples the frame costs the game's work and the trace's draws alone.
            if (state_ == TraceState::ready && !dispatched_ && target_ != 0 && passes() >= target_ && !settled_logged_)
            {
                settled_ms_ += frame_ms;
                if (++settled_frames_ == kSettledFrames)
                {
                    char line[200];
                    std::snprintf(line, sizeof line, "the %u frames after the trace's last pass took %.1f ms each: the game's frame with the trace's draws and "
                        "without its rays.", kSettledFrames, settled_ms_ / kSettledFrames);
                    out.log.push_back(line);
                    settled_logged_ = true;
                }
            }
        }
        polled_at_ = now;
        polled_ = true;
        dispatched_ = false;
        for (size_t i = 0; i < flights_.size(); i++)
        {
            Flight &f = flights_[(next_flight_ + i) % flights_.size()];
            if (!f.pending)
                continue;
            D3D11_QUERY_DATA_TIMESTAMP_DISJOINT disjoint;
            UINT64 begin = 0, middle = 0, end = 0;
            HRESULT hr = context_->GetData(f.disjoint.Get(), &disjoint, sizeof disjoint, D3D11_ASYNC_GETDATA_DONOTFLUSH);
            if (hr == S_OK)
                hr = context_->GetData(f.begin.Get(), &begin, sizeof begin, D3D11_ASYNC_GETDATA_DONOTFLUSH);
            if (hr == S_OK)
                hr = context_->GetData(f.middle.Get(), &middle, sizeof middle, D3D11_ASYNC_GETDATA_DONOTFLUSH);
            if (hr == S_OK)
                hr = context_->GetData(f.end.Get(), &end, sizeof end, D3D11_ASYNC_GETDATA_DONOTFLUSH);
            if (hr == S_FALSE)
                break;  // the later ones are not done either
            uint32_t counts[kCounterSlots] = {};
            D3D11_MAPPED_SUBRESOURCE mapped;
            const HRESULT map = SUCCEEDED(hr) ? context_->Map(f.counters.Get(), 0, D3D11_MAP_READ, D3D11_MAP_FLAG_DO_NOT_WAIT, &mapped) : hr;
            if (map == DXGI_ERROR_WAS_STILL_DRAWING)
                break;
            f.pending = false;
            if (FAILED(map))
            {
                out.log.push_back("a trace dispatch's measurements could not be read (" + hresult_text(FAILED(hr) ? "GetData" : "Map", map) + ")");
                continue;
            }
            std::memcpy(counts, mapped.pData, sizeof counts);
            context_->Unmap(f.counters.Get(), 0);
            const double ms = disjoint.Disjoint || disjoint.Frequency == 0 || end < begin ? -1 : double(end - begin) * 1000.0 / double(disjoint.Frequency);
            if (ms > 0)
            {
                schedule_.batch = next_batch(f.tiles, f.measured, ms, settings.budget_ms, tile_count_);
                schedule_.chunk = next_chunk(f.measured, ms);
            }
            if (f.epoch != epoch_ || state_ != TraceState::ready)
                continue;
            if (ms > 0 && middle >= begin && end >= middle)
            {
                pace_.measured_tiles += f.measured;
                pace_.trace_ms += double(middle - begin) * 1000.0 / double(disjoint.Frequency);
                pace_.gather_ms += double(end - middle) * 1000.0 / double(disjoint.Frequency);
            }
            for (uint32_t k = 0; k < kAllCounters; k++)
                totals_[k] += counts[k];
            const uint32_t rays = counts[static_cast<size_t>(TraceCounter::rays)] + counts[gather_counter(GatherCounter::rays)];
            noise_deviation_ += counts[gather_counter(GatherCounter::deviation)];
            noise_mean_ += counts[gather_counter(GatherCounter::mean)];
            // The gather's error from the noise sums of the dispatches that finished a pass.
            if (f.passes_after > noise_pass_)
            {
                if (noise_mean_ != 0)
                    error_ = gather_error(noise_deviation_, noise_mean_, f.passes_after);
                noise_deviation_ = noise_mean_ = 0;
                noise_pass_ = f.passes_after;
            }
            // The rays of the whole frame, over the time of its first part scaled to all its tiles.
            if (ms > 0 && rays != 0 && f.measured != 0)
                mrays_ = rays / (ms * f.tiles / f.measured) / 1000.0;
            for (uint32_t k = 0; k < kTraceCounters; k++)
                window_[k] += counts[k];
            const uint64_t tested = window_[static_cast<size_t>(TraceCounter::tested)], off = window_[static_cast<size_t>(TraceCounter::off)];
            if (f.passes_after > window_pass_ && tested >= 32)
            {
                if (check_consistency_ && consistency_stale(tested, off))
                {
                    stale("rays from the camera met the scene off the depth buffer at " + std::to_string(off) + " of " + std::to_string(tested)
                        + " grid pixels in pass " + std::to_string(f.passes_after) + " (more than 5%; " + grid_breakdown(window_)
                        + "): the world moved, or the camera sees what the capture did not");
                    out.went_stale = true;
                    return out;
                }
                window_ = {};
                window_pass_ = f.passes_after;
            }
            // The first measurements of a scene's samples are logged even before a pass completes, so a slow trace shows what
            // a tile costs.
            if (measures_logged_ < 3)
            {
                measures_logged_++;
                char line[240];
                std::snprintf(line, sizeof line, "trace measured %u tiles in %.2f ms; the next frames trace %u tiles in submissions of %u (pass %u, %llu rays so far).",
                    f.measured, ms, schedule_.batch, schedule_.chunk, f.passes_after, static_cast<unsigned long long>(totals_[0]));
                out.log.push_back(line);
            }
            const uint32_t target = target_ != 0 ? target_ : std::max(settings.ao_samples, settings.sun_samples);
            if (f.passes_after > logged_pass_ && (power_of_two(f.passes_after) || f.passes_after >= target))
            {
                const std::string pace = pace_text(logged_pass_, f.passes_after);
                pace_ = {};
                logged_pass_ = f.passes_after;
                char line[400];
                std::snprintf(line, sizeof line, "trace pass %u: %llu rays so far, %.2f Mrays/s, %u tiles a frame in submissions of %u (%.1f ms for the first %u "
                    "of the last %u), %llu cut short by a cap (4,096 work or 64 alpha tests a ray), %llu stack overflows, consistency grid "
                    "%llu off of %llu.", f.passes_after, static_cast<unsigned long long>(totals_[0]), mrays_, schedule_.batch, schedule_.chunk, ms, f.measured, f.tiles,
                    static_cast<unsigned long long>(totals_[1]),
                    static_cast<unsigned long long>(totals_[2]), static_cast<unsigned long long>(totals_[4]), static_cast<unsigned long long>(totals_[3]));
                std::string text = line;
                if (totals_[static_cast<size_t>(TraceCounter::off)] != 0)
                    text += " The grid by class: " + grid_breakdown(totals_) + ".";
                if (gathering_)
                {
                    const auto at = [this](GatherCounter g) { return static_cast<unsigned long long>(totals_[gather_counter(g)]); };
                    const unsigned long long hits = at(GatherCounter::direct) + at(GatherCounter::covered) + at(GatherCounter::material) + at(GatherCounter::class_mean);
                    char gathered[320];
                    std::snprintf(gathered, sizeof gathered, " The gather: %llu rays, %llu cut short by a cap, %llu stack overflows; %llu hits by albedo source "
                        "%llu direct, %llu covered, %llu material, %llu class; error %.4f.", at(GatherCounter::rays), at(GatherCounter::guard), at(GatherCounter::overflow),
                        hits, at(GatherCounter::direct), at(GatherCounter::covered), at(GatherCounter::material), at(GatherCounter::class_mean), error_);
                    text += gathered;
                }
                out.log.push_back(text + pace);
            }
        }
        return out;
    }

    bool TraceGpu::copy_for_save(const TraceSave &save, ID3D11Texture2D *normals, ID3D11Texture2D *depth, ID3D11Texture2D *mask, ID3D11Texture2D *irradiance,
        ID3D11Texture2D *albedo, ID3D11Texture2D *irradiance_out)
    {
        if (!history_ || !uploaded_constants_ || (state_ != TraceState::ready && state_ != TraceState::stale))
            return false;
        auto p = std::make_unique<PendingSave>();
        p->save = save;
        p->save.constants = *uploaded_constants_;
        p->save.state = state_;
        p->save.why = state_ == TraceState::stale ? why_ : std::string();
        p->save.passes = passes();
        p->save.counters = totals_;
        p->save.gathering = gathering_ && gather_hit_;
        p->save.target = target_;
        p->save.error = error_;
        p->save.light = light_ ? light_->flags() : 0;
        if (FAILED(staging_buffer(device_.Get(), 16, size_.width * size_.height, p->history)))
            return false;
        if (p->save.gathering && (FAILED(staging_buffer(device_.Get(), 16, size_.width * size_.height, p->gather_hit))
            || FAILED(staging_buffer(device_.Get(), 16, size_.width * size_.height, p->gather_sky))))
            return false;
        ID3D11DeviceContext1 *c = context_.Get();
        c->CopyResource(p->history.Get(), history_.Get());
        if (p->save.gathering)
        {
            c->CopyResource(p->gather_hit.Get(), gather_hit_.Get());
            c->CopyResource(p->gather_sky.Get(), gather_sky_.Get());
            p->save.gather_constants = uploaded_gather_;
        }
        if (!p->normals.copy_from(device_.Get(), c, normals) || !p->depth.copy_from(device_.Get(), c, depth) || !p->mask.copy_from(device_.Get(), c, mask)
            || !p->irradiance.copy_from(device_.Get(), c, irradiance))
            return false;
        // The optional copies leave their files out when they fail.
        if (albedo)
            p->albedo.copy_from(device_.Get(), c, albedo);
        if (irradiance_out)
            p->irradiance_out.copy_from(device_.Get(), c, irradiance_out);
        p->save.size = size_;
        save_ = std::move(p);
        return true;
    }

    void TraceGpu::copy_hdr_for_save(ID3D11Texture2D *hdr)
    {
        if (save_ && !save_->hdr_copied && hdr)
            save_->hdr_copied = save_->hdr.copy_from(device_.Get(), context_.Get(), hdr);
    }

    std::optional<TraceSave> TraceGpu::read_save(bool &failed)
    {
        failed = false;
        if (!save_)
            return std::nullopt;
        // Dropped once it is read or fails, whatever happens, so a failed allocation does not try again every present.
        std::unique_ptr<PendingSave> pending = std::move(save_);
        PendingSave &p = *pending;
        ID3D11DeviceContext1 *c = context_.Get();
        std::vector<uint8_t> normals, depth, mask, irradiance;
        for (const auto &[readback, bytes] : { std::pair { &p.normals, &normals }, std::pair { &p.depth, &depth }, std::pair { &p.mask, &mask },
                 std::pair { &p.irradiance, &irradiance } })
        {
            const Readback::Read r = readback->read(c, *bytes);
            if (r == Readback::Read::not_ready)
            {
                save_ = std::move(pending);
                return std::nullopt;
            }
            if (r == Readback::Read::failed)
            {
                failed = true;
                return std::nullopt;
            }
        }
        // The optional copies: not ready waits, a failed one is left out.
        std::vector<uint8_t> albedo, irradiance_out, hdr;
        for (const auto &[readback, bytes] : { std::pair { &p.albedo, &albedo }, std::pair { &p.irradiance_out, &irradiance_out }, std::pair { &p.hdr, &hdr } })
        {
            if (!readback->copied())
                continue;
            const Readback::Read r = readback->read(c, *bytes);
            if (r == Readback::Read::not_ready)
            {
                save_ = std::move(pending);
                return std::nullopt;
            }
            if (r == Readback::Read::failed)
                bytes->clear();
        }
        TraceSave save = std::move(p.save);
        const size_t pixels = size_t(save.size.width) * save.size.height;
        // The history, then the gather's two buffers when it gathered, each 16 bytes a pixel.
        for (const auto &[buffer, into] : { std::pair { p.history.Get(), &save.history }, std::pair { p.gather_hit.Get(), &save.gather_hit },
                 std::pair { p.gather_sky.Get(), &save.gather_sky } })
        {
            if (!buffer)
                continue;
            D3D11_MAPPED_SUBRESOURCE mapped;
            const HRESULT hr = c->Map(buffer, 0, D3D11_MAP_READ, D3D11_MAP_FLAG_DO_NOT_WAIT, &mapped);
            if (hr == DXGI_ERROR_WAS_STILL_DRAWING)
            {
                p.save = std::move(save);
                save_ = std::move(pending);
                return std::nullopt;
            }
            if (FAILED(hr))
            {
                failed = true;
                return std::nullopt;
            }
            into->resize(pixels * 4);
            std::memcpy(into->data(), mapped.pData, pixels * 16);
            c->Unmap(buffer, 0);
        }
        save.albedo = std::move(albedo);
        save.irradiance_out = std::move(irradiance_out);
        save.hdr = std::move(hdr);
        // The depth copy holds 8 bytes a texel: the float depth, then the stencil and padding.
        save.depth.resize(pixels);
        save.stencil.resize(pixels);
        if (depth.size() == pixels * 8)
            for (size_t i = 0; i < pixels; i++)
            {
                std::memcpy(&save.depth[i], &depth[i * 8], 4);
                save.stencil[i] = depth[i * 8 + 4];
            }
        save.normals.resize(normals.size() / 4);
        std::memcpy(save.normals.data(), normals.data(), save.normals.size() * 4);
        save.mask = std::move(mask);
        save.irradiance = std::move(irradiance);
        return save;
    }
}
